-- ==========================================================================
-- The syllabus workbook, as rows.
--
-- Generated by scripts/import-syllabus.mjs — do not hand-edit; edit the
-- workbook and run it again. Safe to re-run: every id is derived from the
-- workbook, so a second run updates in place instead of adding a copy.
--
-- Sessions come in as drafts. Nothing here is in front of a student until
-- someone publishes it, and re-running never changes a status back.
-- ==========================================================================

begin;

-- Everything hangs under one program, matched by name so this file carries
-- no id that only exists in one database.
do $guard$
begin
  if not exists (select 1 from public.tracks where name = 'Discovery Education Program') then
    raise exception 'no program named %', 'Discovery Education Program';
  end if;
end
$guard$;

-- ---------------------------------------------------------------------
-- Web Design Fundamentals (HTML, CSS, Bootstrap & JS) · 12 sessions
-- ---------------------------------------------------------------------
insert into public.loops
  (id, track_id, code, name, idx, start_date, end_date, status, kind,
   listed, price_egp, lectures_per_week, duration_hours, overview)
select 'lp_sylweb', t.id, 'DSC-L1', 'Web Design Fundamentals (HTML, CSS, Bootstrap & JS)', 1,
       '2026-10-04T09:00:00.000Z', '2026-12-06T09:00:00.000Z', 'planning', 'training',
       true, null, 1, null, '- Session 1 — UI/UX fundmentals
- Session 2 — UI design basics
- Session 3 — Framer (design to prototype)
- Session 4 — HTML & first publish (github + vercel)
- Session 5 — Links - images - lists - forms
- Session 6 — CSS fundmentals
- Session 7 — Layout & responsive design
- Session 8 — Bootstrap part 1 (grid & utilities)
- Session 9 — Bootstrap part 2 (UI elements)
- Session 10 — Javascript fundmentals
- Session 11 — Javascript for landing pages
- Session 12 — Graduation project - my professional landing page'
  from public.tracks t where t.name = 'Discovery Education Program'
on conflict (id) do update set
  code = excluded.code, name = excluded.name, idx = excluded.idx,
  overview = excluded.overview;

