hnical","question":"What is database","options":[],"points":5,"required":true}]},{"id":"ttl_syliot0106","order":5,"name":"What is realtime database","summary":"database that sends the new value to all devices immediately when it changes","kind":"topic","video":null,"estimatedMin":5,"materials":[],"tasks":[{"id":"tsk_syliot010601","order":0,"kind":"short","category":"technical","question":"What is realtime database","options":[],"points":5,"required":true}]},{"id":"ttl_syliot0107","order":6,"name":"What is firebase","summary":"free google service that gives us a realtime database , authentication and hosting","kind":"topic","video":null,"estimatedMin":5,"materials":[],"tasks":[{"id":"tsk_syliot010701","order":0,"kind":"short","category":"technical","question":"What is firebase","options":[],"points":5,"required":true}]},{"id":"ttl_syliot0108","order":7,"name":"Firebase realtime database structure (JSON tree)","summary":"data saved as tree: /home/livingroom/temperature = 28 , like folders and files","kind":"topic","video":null,"estimatedMin":5,"materials":[],"tasks":[{"id":"tsk_syliot010801","order":0,"kind":"short","category":"technical","question":"Firebase realtime database structure (JSON tree)","options":[],"points":5,"required":true}]},{"id":"ttl_syliot0109","order":8,"name":"IoT system parts","summary":"device (esp32 + sensors or robot) → internet → firebase database → dashboard website → user mobile","kind":"topic","video":null,"estimatedMin":5,"materials":[],"tasks":[{"id":"tsk_syliot010901","order":0,"kind":"short","category":"technical","question":"IoT system parts","options":[],"points":5,"required":true}]},{"id":"ttl_syliot0110","order":9,"name":"Example of IoT systems","summary":"smart home apps , car tracking , delivery robots , farm irrigation , factory machines monitoring","kind":"topic","video":null,"estimatedMin":5,"materials":[],"tasks":[{"id":"tsk_syliot011001","order":0,"kind":"short","category":"technical","question":"Example of IoT systems","options":[],"points":5,"required":true}]},{"id":"ttl_syliot0111","order":10,"name":"What we will build in this course","summary":"smart home system on the internet + robot controlled from a website from anywhere in the world","kind":"topic","video":null,"estimatedMin":5,"materials":[],"tasks":[{"id":"tsk_syliot011101","order":0,"kind":"short","category":"technical","question":"What we will build in this course","options":[],"points":5,"required":true}]},{"id":"ttl_syliot0112","order":11,"name":"Create your firebase project & database","summary":"every student creates his own firebase project and realtime database and gets the database url and api key","kind":"project","video":null,"estimatedMin":20,"materials":[{"id":"mat_syliot011201v","order":0,"kind":"video","category":"video","name":"Step 1 — Hardware used","url":"","size":0,"note":"laptop or computer - google account - internet"},{"id":"mat_syliot011202v","order":1,"kind":"video","category":"video","name":"Step 2 — Wiring diagram","url":"","size":0,"note":"no wiring"},{"id":"mat_syliot011203v","order":2,"kind":"video","category":"video","name":"Step 3 — Coding","url":"","size":0,"note":"no coding , steps: firebase console → add project → build → realtime database → create database → test mode → copy database url + api key from project settings"},{"id":"mat_syliot011204v","order":3,"kind":"video","category":"video","name":"Step 4 — Show result","url":"","size":0,"note":"(screenshot of the empty database)"}],"tasks":[{"id":"tsk_syliot011201","order":0,"kind":"short","category":"technical","question":"Step 1 — Hardware used","hint":"laptop or computer - google account - internet","options":[],"points":5,"required":true},{"id":"tsk_syliot011202","order":1,"kind":"short","category":"technical","question":"Step 2 — Wiring diagram","hint":"no wiring","options":[],"points":5,"required":true},{"id":"tsk_syliot011203","order":2,"kind":"short","category":"technical","question":"Step 3 — Coding","hint":"no coding , steps: fi